/**
 * Reads metadata through the Tooling API and compares it with a Git branch.
 * This org is read through the RLY_Org_Self Named Credential (read-only integration user).
 */
public with sharing class RlyChangeService {

    public class OrgChangeException extends Exception {}

    @TestVisible private static final String TOOLING_PATH = '/services/data/v62.0/tooling/query/?q=';
    private static final Integer MAX_PAGES = 10;

    /** Where Tooling queries go: this org, through the Named Credential. */
    public class OrgEndpoint {
        public String root;   // callout:RLY_Org_Self or https://target.my.salesforce.com
        public String token;  // null for the Named Credential
        public String label;
        public OrgEndpoint(String root, String token, String label) {
            this.root = root;
            this.token = token;
            this.label = label;
        }
    }

    public static final OrgEndpoint THIS_ORG = new OrgEndpoint('callout:RLY_Org_Self', null, 'this org');

    public class ChangeItem {
        @AuraEnabled public String key;
        @AuraEnabled public String metadataType;
        @AuraEnabled public String name;
        @AuraEnabled public String changeType;
        @AuraEnabled public String lastModifiedByName;
        @AuraEnabled public String lastModifiedById;
        @AuraEnabled public Datetime lastModified;
        @AuraEnabled public Boolean mine;
    }

    public class SourceFile {
        @AuraEnabled public String path;
        @AuraEnabled public String orgSource;
        @AuraEnabled public String branchSource;
        @AuraEnabled public Boolean inBranch;
    }

    /** Tooling object and name field for each type the page can detect. */
    private static final Map<String, List<String>> TOOLING_FOR_TYPE = new Map<String, List<String>>{
        'ApexClass' => new List<String>{ 'ApexClass', 'Name' },
        'ApexTrigger' => new List<String>{ 'ApexTrigger', 'Name' },
        'ApexPage' => new List<String>{ 'ApexPage', 'Name' },
        'ApexComponent' => new List<String>{ 'ApexComponent', 'Name' },
        'LightningComponentBundle' => new List<String>{ 'LightningComponentBundle', 'DeveloperName' },
        'AuraDefinitionBundle' => new List<String>{ 'AuraDefinitionBundle', 'DeveloperName' },
        'Flow' => new List<String>{ 'FlowDefinition', 'DeveloperName' },
        'CustomObject' => new List<String>{ 'CustomObject', 'DeveloperName' }
    };

    /**
     * More types the Select step can detect, read from the same org through Tooling or REST queries.
     * format: {name} the record's name, {parent} the object (resolved from its Id when needed),
     * {folder} the email template folder; QuickAction drops the parent for global actions.
     */
    private class TypeSpec {
        public String api;           // tooling or data
        public String sobjectName;
        public String nameField;
        public String parentField;
        public String format;
        public Boolean hasModifiedBy;
        public String extraFilter;
        public TypeSpec(String api, String sobjectName, String nameField, String parentField, String format,
                        Boolean hasModifiedBy, String extraFilter) {
            this.api = api;
            this.sobjectName = sobjectName;
            this.nameField = nameField;
            this.parentField = parentField;
            this.format = format;
            this.hasModifiedBy = hasModifiedBy;
            this.extraFilter = extraFilter;
        }
    }

    @TestVisible
    private static final Map<String, TypeSpec> MORE_TYPES = new Map<String, TypeSpec>{
        'CustomField' => new TypeSpec('tooling', 'CustomField', 'DeveloperName', 'TableEnumOrId', '{parent}.{name}__c', true, null),
        'Layout' => new TypeSpec('tooling', 'Layout', 'Name', 'TableEnumOrId', '{parent}-{name}', true, null),
        'ValidationRule' => new TypeSpec('tooling', 'ValidationRule', 'ValidationName', 'EntityDefinitionId', '{parent}.{name}', true, null),
        'RecordType' => new TypeSpec('data', 'RecordType', 'DeveloperName', 'SobjectType', '{parent}.{name}', true, null),
        'PermissionSet' => new TypeSpec('tooling', 'PermissionSet', 'Name', null, '{name}', true, 'IsOwnedByProfile = false'),
        'PermissionSetGroup' => new TypeSpec('data', 'PermissionSetGroup', 'DeveloperName', null, '{name}', true, null),
        'CustomTab' => new TypeSpec('tooling', 'CustomTab', 'DeveloperName', null, '{name}', true, null),
        'FlexiPage' => new TypeSpec('tooling', 'FlexiPage', 'DeveloperName', null, '{name}', false, null),
        'StaticResource' => new TypeSpec('tooling', 'StaticResource', 'Name', null, '{name}', true, null),
        'CustomLabel' => new TypeSpec('tooling', 'ExternalString', 'Name', null, '{name}', true, null),
        'QuickAction' => new TypeSpec('tooling', 'QuickActionDefinition', 'DeveloperName', 'SobjectType', '{parent}.{name}', true, null),
        'GlobalValueSet' => new TypeSpec('tooling', 'GlobalValueSet', 'DeveloperName', null, '{name}', true, null),
        'EmailTemplate' => new TypeSpec('data', 'EmailTemplate', 'DeveloperName', 'Folder.DeveloperName', '{parent}/{name}', true, null)
    };

    @TestVisible private static final String DATA_PATH = '/services/data/v62.0/query/?q=';

    /** Every type the Select step can detect, in display order. */
    public static List<String> detectableTypes() {
        List<String> types = new List<String>(TOOLING_FOR_TYPE.keySet());
        types.addAll(MORE_TYPES.keySet());
        return types;
    }

    /** Repo folder and file suffix for each type deletions can be detected for ('' = folder per component). */
    private static final Map<String, List<String>> FOLDER_FOR_TYPE = new Map<String, List<String>>{
        'ApexClass' => new List<String>{ 'classes', '.cls' },
        'ApexTrigger' => new List<String>{ 'triggers', '.trigger' },
        'ApexPage' => new List<String>{ 'pages', '.page' },
        'ApexComponent' => new List<String>{ 'components', '.component' },
        'LightningComponentBundle' => new List<String>{ 'lwc', '' },
        'AuraDefinitionBundle' => new List<String>{ 'aura', '' },
        'Flow' => new List<String>{ 'flows', '.flow-meta.xml' }
    };

    /** Folders checked to label changes as New (objects too, which deletions skip). */
    private static final Map<String, List<String>> NEW_FOLDERS = new Map<String, List<String>>{
        'ApexClass' => new List<String>{ 'classes', '.cls' },
        'ApexTrigger' => new List<String>{ 'triggers', '.trigger' },
        'ApexPage' => new List<String>{ 'pages', '.page' },
        'ApexComponent' => new List<String>{ 'components', '.component' },
        'LightningComponentBundle' => new List<String>{ 'lwc', '' },
        'AuraDefinitionBundle' => new List<String>{ 'aura', '' },
        'Flow' => new List<String>{ 'flows', '.flow-meta.xml' },
        'CustomObject' => new List<String>{ 'objects', '' }
    };

    private static final Map<String, String> AURA_SUFFIX = new Map<String, String>{
        'COMPONENT' => '.cmp', 'APPLICATION' => '.app', 'EVENT' => '.evt', 'INTERFACE' => '.intf',
        'CONTROLLER' => 'Controller.js', 'HELPER' => 'Helper.js', 'RENDERER' => 'Renderer.js',
        'STYLE' => '.css', 'DOCUMENTATION' => '.auradoc', 'DESIGN' => '.design', 'SVG' => '.svg',
        'TOKENS' => '.tokens'
    };

    // ---------- changed in the org ----------

    public static List<ChangeItem> listChanges(List<String> types, Integer days, Boolean onlyMine) {
        return listChanges(types, days, onlyMine == true ? 'me' : 'anyone', null);
    }

    /**
     * Components changed in this org.
     * changedBy: 'me' (default) or 'anyone'.
     * days: null or 0 for any time. nameSearch: part of the component name.
     */
    public static List<ChangeItem> listChanges(List<String> types, Integer days, String changedBy, String nameSearch) {
        String term = String.isBlank(nameSearch) ? null : nameSearch.trim();
        Boolean anyDate = days == null || days <= 0;
        Integer window = anyDate ? 3650 : Math.min(days, 3650);
        String since = Datetime.now().addDays(-window).formatGmt('yyyy-MM-dd\'T\'HH:mm:ss\'Z\'');
        String me = String.valueOf(UserInfo.getUserId());
        Boolean mineOnly = changedBy != 'anyone';
        List<ChangeItem> items = new List<ChangeItem>();
        List<List<Object>> withParent = new List<List<Object>>(); // [item, spec, raw parent]
        for (String t : types) {
            String metadataType = t.trim();
            List<String> tooling = TOOLING_FOR_TYPE.get(metadataType);
            if (tooling == null) {
                TypeSpec spec = MORE_TYPES.get(metadataType);
                if (spec != null) {
                    listMore(metadataType, spec, anyDate, since, mineOnly, me, term, items, withParent);
                }
                continue;
            }
            List<String> filters = new List<String>{ 'NamespacePrefix = null' };
            if (!anyDate) {
                filters.add('LastModifiedDate >= ' + since);
            }
            if (mineOnly) {
                filters.add('LastModifiedById = \'' + me + '\'');
            }
            if (term != null) {
                filters.add(tooling[1] + ' LIKE \'%' + likeSafe(term) + '%\'');
            }
            String soql = 'SELECT Id, ' + tooling[1] + ', LastModifiedDate, LastModifiedById, LastModifiedBy.Name FROM '
                + tooling[0] + ' WHERE ' + String.join(filters, ' AND ')
                + ' ORDER BY LastModifiedDate DESC LIMIT 200';
            for (Object o : query(soql, 1)) {
                Map<String, Object> rec = (Map<String, Object>) o;
                ChangeItem item = new ChangeItem();
                item.metadataType = metadataType;
                item.name = String.valueOf(rec.get(tooling[1])) + (metadataType == 'CustomObject' ? '__c' : '');
                item.key = metadataType + ':' + item.name;
                item.changeType = 'Modified';
                Map<String, Object> modifiedBy = (Map<String, Object>) rec.get('LastModifiedBy');
                item.lastModifiedByName = modifiedBy == null ? null : String.valueOf(modifiedBy.get('Name'));
                item.lastModifiedById = String.valueOf(rec.get('LastModifiedById'));
                item.lastModified = parseDate(String.valueOf(rec.get('LastModifiedDate')));
                item.mine = item.lastModifiedById == me;
                items.add(item);
            }
        }
        nameWithParents(withParent);
        return items;
    }

    /** Recent changes of one of the MORE_TYPES; items that need their object's name are named later. */
    private static void listMore(String metadataType, TypeSpec spec, Boolean anyDate, String since, Boolean mineOnly, String me,
                                 String term, List<ChangeItem> items, List<List<Object>> withParent) {
        List<String> filters = new List<String>{ 'NamespacePrefix = null' };
        if (spec.extraFilter != null) {
            filters.add(spec.extraFilter);
        }
        if (!anyDate) {
            filters.add('LastModifiedDate >= ' + since);
        }
        if (mineOnly && spec.hasModifiedBy) {
            filters.add('LastModifiedById = \'' + me + '\'');
        }
        if (term != null) {
            filters.add(spec.nameField + ' LIKE \'%' + likeSafe(term) + '%\'');
        }
        String fields = 'Id, ' + spec.nameField + (spec.parentField == null ? '' : ', ' + spec.parentField)
            + ', LastModifiedDate' + (spec.hasModifiedBy ? ', LastModifiedById, LastModifiedBy.Name' : '');
        String soql = 'SELECT ' + fields + ' FROM ' + spec.sobjectName + ' WHERE ' + String.join(filters, ' AND ')
            + ' ORDER BY LastModifiedDate DESC LIMIT 200';
        for (Object o : query(THIS_ORG, soql, 1, spec.api == 'data')) {
            Map<String, Object> rec = (Map<String, Object>) o;
            Object rawName = rec.get(spec.nameField);
            if (rawName == null) {
                continue; // for example object tabs, which have no developer name of their own
            }
            ChangeItem item = new ChangeItem();
            item.metadataType = metadataType;
            item.name = String.valueOf(rawName);
            item.changeType = 'Modified';
            if (spec.hasModifiedBy) {
                Map<String, Object> modifiedBy = (Map<String, Object>) rec.get('LastModifiedBy');
                item.lastModifiedByName = modifiedBy == null ? null : String.valueOf(modifiedBy.get('Name'));
                item.lastModifiedById = String.valueOf(rec.get('LastModifiedById'));
            } else {
                item.lastModifiedByName = 'Not recorded';
            }
            item.lastModified = parseDate(String.valueOf(rec.get('LastModifiedDate')));
            item.mine = item.lastModifiedById == me;
            String parent = spec.parentField == null ? null : parentValue(rec, spec.parentField);
            item.name = spec.format.replace('{name}', item.name).replace('{parent}', parent == null ? '' : parent);
            if (metadataType == 'QuickAction' && (parent == null || parent == 'Global')) {
                item.name = String.valueOf(rawName);
            }
            if (metadataType == 'EmailTemplate' && parent == null) {
                item.name = 'unfiled$public/' + String.valueOf(rawName);
            }
            item.key = metadataType + ':' + item.name;
            items.add(item);
            if (parent != null && parent.startsWith('01I')) {
                withParent.add(new List<Object>{ item, spec, parent, String.valueOf(rawName) });
            }
        }
    }

    /** A parent value, following one relationship (Folder.DeveloperName) when the field has a dot. */
    private static String parentValue(Map<String, Object> rec, String field) {
        if (!field.contains('.')) {
            return rec.get(field) == null ? null : String.valueOf(rec.get(field));
        }
        Object rel = rec.get(field.substringBefore('.'));
        if (!(rel instanceof Map<String, Object>)) {
            return null;
        }
        Object v = ((Map<String, Object>) rel).get(field.substringAfter('.'));
        return v == null ? null : String.valueOf(v);
    }

    /** Custom objects come back as Ids (01I...): swap them for API names in one EntityDefinition query. */
    private static void nameWithParents(List<List<Object>> withParent) {
        if (withParent.isEmpty()) {
            return;
        }
        Set<String> ids = new Set<String>();
        for (List<Object> row : withParent) {
            ids.add(String.valueOf(row[2]).left(15));
        }
        Map<String, String> apiNames = new Map<String, String>();
        String idList = '\'' + String.join(new List<String>(ids), '\',\'') + '\'';
        for (Object o : query(THIS_ORG, 'SELECT DurableId, QualifiedApiName FROM EntityDefinition WHERE DurableId IN (' + idList + ')', 1, false)) {
            Map<String, Object> rec = (Map<String, Object>) o;
            apiNames.put(String.valueOf(rec.get('DurableId')).left(15), String.valueOf(rec.get('QualifiedApiName')));
        }
        for (List<Object> row : withParent) {
            ChangeItem item = (ChangeItem) row[0];
            TypeSpec spec = (TypeSpec) row[1];
            String objectName = apiNames.get(String.valueOf(row[2]).left(15));
            if (objectName != null) {
                item.name = spec.format.replace('{name}', String.valueOf(row[3])).replace('{parent}', objectName);
                item.key = item.metadataType + ':' + item.name;
            }
        }
    }

    /** Keeps letters, digits, space, dot, dash and underscore, and escapes _ so it matches literally. */
    @TestVisible
    private static String likeSafe(String term) {
        String cleaned = term.replaceAll('[^A-Za-z0-9_ .-]', '');
        return String.escapeSingleQuotes(cleaned).replace('_', '\\_').replace('%', '\\%');
    }

    /** Labels each change New when the target branch doesn't have it yet, Modified otherwise. */
    public static void markNew(List<ChangeItem> items, RlyGitProvider git, String ref, String sourcePath) {
        Set<String> types = new Set<String>();
        for (ChangeItem i : items) {
            if (NEW_FOLDERS.containsKey(i.metadataType)) {
                types.add(i.metadataType);
            }
        }
        if (types.isEmpty()) {
            return;
        }
        Set<String> folders = folderNames(git, sourcePath, ref);
        Map<String, Set<String>> inBranch = new Map<String, Set<String>>();
        for (String t : types) {
            inBranch.put(t, branchNames(git, sourcePath, ref, NEW_FOLDERS.get(t), folders).keySet());
        }
        for (ChangeItem i : items) {
            Set<String> names = inBranch.get(i.metadataType);
            if (names != null) {
                i.changeType = names.contains(i.name.toLowerCase()) ? 'Modified' : 'New';
            }
        }
    }

    private static Set<String> folderNames(RlyGitProvider git, String sourcePath, String ref) {
        Set<String> names = new Set<String>();
        for (RlyGitProvider.Entry e : git.listDir(sourcePath, ref)) {
            if (e.kind == 'dir') {
                names.add(e.name);
            }
        }
        return names;
    }

    /** Lower-case component name to its display name, from one type folder of a branch. */
    private static Map<String, String> branchNames(RlyGitProvider git, String sourcePath, String ref, List<String> folder, Set<String> folders) {
        Map<String, String> names = new Map<String, String>();
        if (!folders.contains(folder[0])) {
            return names;
        }
        for (RlyGitProvider.Entry e : git.listDir(sourcePath + '/' + folder[0], ref)) {
            String name;
            if (folder[1] == '') {
                name = e.kind == 'dir' ? e.name : null;
            } else if (e.name.endsWith(folder[1])) {
                name = e.name.removeEnd(folder[1]);
            }
            if (name != null) {
                names.put(name.toLowerCase(), name);
            }
        }
        return names;
    }

    /** Lower-case names of one type in an org. */
    private static Set<String> orgNames(OrgEndpoint ep, String metadataType) {
        List<String> tooling = TOOLING_FOR_TYPE.get(metadataType);
        Set<String> names = new Set<String>();
        for (Object o : query(ep, 'SELECT ' + tooling[1] + ' FROM ' + tooling[0] + ' WHERE NamespacePrefix = null', MAX_PAGES)) {
            names.add(String.valueOf(((Map<String, Object>) o).get(tooling[1])).toLowerCase());
        }
        return names;
    }

    // ---------- compared with the target branch ----------

    public class Comparison {
        @AuraEnabled public String key;
        @AuraEnabled public String status;   // New, Different, Same, Exists (in the target, not compared here)
        @AuraEnabled public Integer added;
        @AuraEnabled public Integer removed;
    }

    /** Where each type lives in the repository: folder, file suffix ('' = folder per component). */
    private static final Map<String, List<String>> XML_PATHS = new Map<String, List<String>>{
        'Flow' => new List<String>{ 'flows/{name}.flow-meta.xml' },
        'CustomObject' => new List<String>{ 'objects/{name}/{name}.object-meta.xml' },
        'CustomField' => new List<String>{ 'objects/{parent}/fields/{child}.field-meta.xml' },
        'ValidationRule' => new List<String>{ 'objects/{parent}/validationRules/{child}.validationRule-meta.xml' },
        'RecordType' => new List<String>{ 'objects/{parent}/recordTypes/{child}.recordType-meta.xml' },
        'Layout' => new List<String>{ 'layouts/{name}.layout-meta.xml' },
        'PermissionSet' => new List<String>{ 'permissionsets/{name}.permissionset-meta.xml' },
        'PermissionSetGroup' => new List<String>{ 'permissionsetgroups/{name}.permissionsetgroup-meta.xml' },
        'CustomTab' => new List<String>{ 'tabs/{name}.tab-meta.xml' },
        'FlexiPage' => new List<String>{ 'flexipages/{name}.flexipage-meta.xml' },
        'StaticResource' => new List<String>{ 'staticresources/{name}.resource-meta.xml' },
        'QuickAction' => new List<String>{ 'quickActions/{name}.quickAction-meta.xml' },
        'GlobalValueSet' => new List<String>{ 'globalValueSets/{name}.globalValueSet-meta.xml' },
        'EmailTemplate' => new List<String>{ 'email/{name}.email-meta.xml' }
    };

    /**
     * Compares changes with the target branch: New when the branch doesn't have the component,
     * Same or Different for code (by Git blob hash, so unchanged files aren't downloaded),
     * Exists for XML types (their files are compared in the pull request).
     * Meant for one page at a time: about one Tooling query per code component.
     */
    public static List<Comparison> compare(List<ChangeItem> items, RlyGitProvider git, String ref, String sourcePath) {
        Map<String, String> tree = git.treeShas(ref);
        List<Comparison> out = new List<Comparison>();
        if (tree == null) {
            // Providers without a tree listing: New or Exists, from the folder listings.
            List<ChangeItem> copy = new List<ChangeItem>();
            for (ChangeItem i : items) {
                ChangeItem c = new ChangeItem();
                c.key = i.key;
                c.metadataType = i.metadataType;
                c.name = i.name;
                copy.add(c);
            }
            markNew(copy, git, ref, sourcePath);
            for (ChangeItem c : copy) {
                out.add(result(c.key, c.changeType == 'New' ? 'New' : 'Exists', null, null));
            }
            return out;
        }
        String root = sourcePath.removeEnd('/') + '/';
        Map<String, String> lowerTree = new Map<String, String>();
        for (String path : tree.keySet()) {
            lowerTree.put(path.toLowerCase(), path);
        }
        for (ChangeItem i : items) {
            try {
                out.add(compareOne(i, git, ref, root, tree, lowerTree));
            } catch (Exception e) {
                out.add(result(i.key, 'Error', null, null));
            }
        }
        return out;
    }

    private static Comparison compareOne(ChangeItem i, RlyGitProvider git, String ref, String root,
                                         Map<String, String> tree, Map<String, String> lowerTree) {
        if (FOLDER_FOR_TYPE.containsKey(i.metadataType) && i.metadataType != 'Flow') {
            Map<String, String> files = orgFiles(THIS_ORG, i.metadataType, i.name, root.removeEnd('/'));
            Boolean anyInBranch = false;
            Boolean different = false;
            Integer added = 0;
            Integer removed = 0;
            for (String path : files.keySet()) {
                if (path.endsWith('.cls-meta.xml') || path.endsWith('.trigger-meta.xml')) {
                    continue; // written by the CLI, not stored in the org as-is
                }
                String branchPath = lowerTree.get(path.toLowerCase());
                if (branchPath == null) {
                    different = true;
                    added += lineCount(files.get(path));
                    continue;
                }
                anyInBranch = true;
                String orgText = files.get(path) == null ? '' : files.get(path);
                if (blobSha(orgText) == tree.get(branchPath)) {
                    continue;
                }
                // Hashes differ: compare the text, ignoring line endings and trailing blank lines.
                String branchText = git.getFileRaw(branchPath, ref);
                if (normalize(orgText) != normalize(branchText)) {
                    different = true;
                    Integer[] counts = lineDelta(branchText, orgText);
                    added += counts[0];
                    removed += counts[1];
                }
            }
            if (!anyInBranch) {
                return result(i.key, 'New', added, 0);
            }
            return different ? result(i.key, 'Different', added, removed) : result(i.key, 'Same', 0, 0);
        }
        String path = xmlPath(i);
        if (path == null) {
            return result(i.key, 'Exists', null, null);
        }
        return result(i.key, lowerTree.containsKey((root + path).toLowerCase()) ? 'Exists' : 'New', null, null);
    }

    /** Repository path (under the source path) of an XML type, or null when it isn't one file. */
    @TestVisible
    private static String xmlPath(ChangeItem i) {
        List<String> pattern = XML_PATHS.get(i.metadataType);
        if (pattern == null) {
            return null;
        }
        String name = i.name;
        String parent = name.contains('.') ? name.substringBefore('.') : name.substringBefore('-');
        String child = name.contains('.') ? name.substringAfter('.') : name;
        return pattern[0].replace('{name}', name).replace('{parent}', parent).replace('{child}', child);
    }

    private static Comparison result(String key, String status, Integer added, Integer removed) {
        Comparison c = new Comparison();
        c.key = key;
        c.status = status;
        c.added = added;
        c.removed = removed;
        return c;
    }

    /** Git's blob hash of a text file: sha1("blob <bytes>\0<content>"). */
    @TestVisible
    private static String blobSha(String content) {
        Blob body = Blob.valueOf(content);
        String hex = EncodingUtil.convertToHex(Blob.valueOf('blob ' + body.size())) + '00' + EncodingUtil.convertToHex(body);
        return EncodingUtil.convertToHex(Crypto.generateDigest('SHA1', EncodingUtil.convertFromHex(hex)));
    }

    @TestVisible
    private static String normalize(String text) {
        return text == null ? '' : text.replace('\r\n', '\n').replaceAll('\\s+$', '');
    }

    private static Integer lineCount(String text) {
        return String.isBlank(text) ? 0 : normalize(text).split('\n').size();
    }

    /** Lines only in the org version (added) and only in the branch version (removed), by content. */
    @TestVisible
    private static Integer[] lineDelta(String branchText, String orgText) {
        Map<String, Integer> counts = new Map<String, Integer>();
        for (String l : normalize(branchText).split('\n')) {
            counts.put(l, (counts.containsKey(l) ? counts.get(l) : 0) + 1);
        }
        Integer added = 0;
        for (String l : normalize(orgText).split('\n')) {
            Integer n = counts.get(l);
            if (n == null || n == 0) {
                added++;
            } else {
                counts.put(l, n - 1);
            }
        }
        Integer removed = 0;
        for (Integer n : counts.values()) {
            removed += n;
        }
        return new Integer[]{ added, removed };
    }

    // ---------- in the branch but not in the org ----------

    /**
     * Code components present in the target branch but missing from this org: candidates
     * for deletion. Covers Apex classes, triggers, Visualforce pages and components, LWC,
     * Aura and flows. Other types are added by hand on the Select step.
     */
    public static List<ChangeItem> listDeletions(RlyGitProvider git, String ref, String sourcePath, List<String> types) {
        Set<String> folders = folderNames(git, sourcePath, ref);
        List<ChangeItem> items = new List<ChangeItem>();
        for (String t : types) {
            String metadataType = t.trim();
            List<String> folder = FOLDER_FOR_TYPE.get(metadataType);
            if (folder == null) {
                continue;
            }
            Map<String, String> inBranch = branchNames(git, sourcePath, ref, folder, folders);
            if (inBranch.isEmpty()) {
                continue;
            }
            Set<String> missing = inBranch.keySet().clone();
            missing.removeAll(orgNames(THIS_ORG, metadataType));
            for (String lower : missing) {
                items.add(deletion(metadataType, inBranch.get(lower), 'In ' + ref + ', not in this org'));
            }
        }
        return items;
    }

    private static ChangeItem deletion(String metadataType, String name, String note) {
        ChangeItem item = new ChangeItem();
        item.metadataType = metadataType;
        item.name = name;
        item.key = metadataType + ':' + name;
        item.changeType = 'Deleted';
        item.lastModifiedByName = note;
        item.mine = false;
        return item;
    }

    // ---------- sources for the diff ----------

    /** Org and branch versions of code components. Empty for XML-only types (compared in the PR). */
    public static List<SourceFile> getSources(String metadataType, String name, String sourcePath,
                                              RlyGitProvider git, String ref) {
        Map<String, String> orgFiles = orgFiles(THIS_ORG, metadataType, name, sourcePath);
        List<SourceFile> files = new List<SourceFile>();
        for (String path : orgFiles.keySet()) {
            SourceFile f = new SourceFile();
            f.path = path;
            f.orgSource = orgFiles.get(path);
            f.branchSource = git.getFileRaw(path, ref);
            f.inBranch = f.branchSource != null;
            files.add(f);
        }
        return files;
    }

    private static Map<String, String> orgFiles(OrgEndpoint ep, String metadataType, String name, String sourcePath) {
        String safe = String.escapeSingleQuotes(name);
        Map<String, String> orgFiles = new Map<String, String>();
        if (metadataType == 'ApexClass' || metadataType == 'ApexTrigger') {
            List<Object> recs = query(ep, 'SELECT Body, ApiVersion, Status FROM ' + metadataType
                + ' WHERE NamespacePrefix = null AND Name = \'' + safe + '\' LIMIT 1', 1);
            if (!recs.isEmpty()) {
                Map<String, Object> rec = (Map<String, Object>) recs[0];
                List<String> folder = FOLDER_FOR_TYPE.get(metadataType);
                String path = sourcePath + '/' + folder[0] + '/' + name + folder[1];
                orgFiles.put(path, String.valueOf(rec.get('Body')));
                String meta = apexMeta(metadataType, rec.get('ApiVersion'), rec.get('Status'));
                if (meta != null) {
                    orgFiles.put(path + '-meta.xml', meta);
                }
            }
        } else if (metadataType == 'ApexPage' || metadataType == 'ApexComponent') {
            List<Object> recs = query(ep, 'SELECT Markup FROM ' + metadataType
                + ' WHERE NamespacePrefix = null AND Name = \'' + safe + '\' LIMIT 1', 1);
            if (!recs.isEmpty()) {
                List<String> folder = FOLDER_FOR_TYPE.get(metadataType);
                orgFiles.put(sourcePath + '/' + folder[0] + '/' + name + folder[1],
                    String.valueOf(((Map<String, Object>) recs[0]).get('Markup')));
            }
        } else if (metadataType == 'LightningComponentBundle') {
            for (Object o : query(ep, 'SELECT FilePath, Source FROM LightningComponentResource'
                    + ' WHERE LightningComponentBundle.DeveloperName = \'' + safe + '\'', 1)) {
                Map<String, Object> rec = (Map<String, Object>) o;
                orgFiles.put(sourcePath + '/' + String.valueOf(rec.get('FilePath')), String.valueOf(rec.get('Source')));
            }
        } else if (metadataType == 'AuraDefinitionBundle') {
            for (Object o : query(ep, 'SELECT DefType, Source FROM AuraDefinition'
                    + ' WHERE AuraDefinitionBundle.DeveloperName = \'' + safe + '\'', 1)) {
                Map<String, Object> rec = (Map<String, Object>) o;
                String suffix = AURA_SUFFIX.get(String.valueOf(rec.get('DefType')));
                if (suffix != null) {
                    orgFiles.put(sourcePath + '/aura/' + name + '/' + name + suffix, String.valueOf(rec.get('Source')));
                }
            }
        }
        return orgFiles;
    }

    /** The -meta.xml file the Salesforce CLI writes for an Apex class or trigger, so Review can compare it too. */
    @TestVisible
    private static String apexMeta(String metadataType, Object apiVersion, Object status) {
        if (apiVersion == null) {
            return null;
        }
        String version = String.valueOf(apiVersion);
        if (!version.contains('.')) {
            version += '.0';
        }
        return '<?xml version="1.0" encoding="UTF-8"?>\n<' + metadataType + ' xmlns="http://soap.sforce.com/2006/04/metadata">\n'
            + '    <apiVersion>' + version + '</apiVersion>\n'
            + '    <status>' + (status == null ? 'Active' : String.valueOf(status)) + '</status>\n'
            + '</' + metadataType + '>\n';
    }

    // ---------- helpers ----------

    /** Runs a Tooling query in this org. */
    private static List<Object> query(String soql, Integer maxPages) {
        return query(THIS_ORG, soql, maxPages);
    }

    /** Runs a Tooling query and follows nextRecordsUrl for up to maxPages pages. */
    private static List<Object> query(OrgEndpoint ep, String soql, Integer maxPages) {
        return query(ep, soql, maxPages, false);
    }

    /** Runs a Tooling query, or a REST (data) query when dataApi is true. */
    private static List<Object> query(OrgEndpoint ep, String soql, Integer maxPages, Boolean dataApi) {
        List<Object> all = new List<Object>();
        String endpoint = ep.root + (dataApi == true ? DATA_PATH : TOOLING_PATH) + EncodingUtil.urlEncode(soql, 'UTF-8');
        for (Integer page = 0; page < maxPages && endpoint != null; page++) {
            HttpRequest req = new HttpRequest();
            req.setMethod('GET');
            req.setEndpoint(endpoint);
            req.setTimeout(20000);
            HttpResponse res = new Http().send(req);
            if (res.getStatusCode() != 200) {
                throw new OrgChangeException((dataApi == true ? 'Query' : 'Tooling API query') + ' in ' + ep.label + ' failed with HTTP ' + res.getStatusCode()
                    + (ep.token == null ? '. Check the RLY_Org_Self Named Credential. ' : '. ') + res.getBody().left(300));
            }
            Map<String, Object> body = (Map<String, Object>) JSON.deserializeUntyped(res.getBody());
            List<Object> records = (List<Object>) body.get('records');
            if (records != null) {
                all.addAll(records);
            }
            Object next = body.get('nextRecordsUrl');
            endpoint = (next == null || (Boolean) body.get('done') == true) ? null : ep.root + String.valueOf(next);
        }
        return all;
    }

    @TestVisible
    private static Datetime parseDate(String value) {
        if (String.isBlank(value)) {
            return null;
        }
        return (Datetime) JSON.deserialize('"' + value + '"', Datetime.class);
    }
